function formatPrice(amount) { return "COP " + new Intl.NumberFormat(language === "es" ? "es-CO" : "en-US", {maximumFractionDigits:0}).format(amount); }
let bag={};try{const saved=JSON.parse(localStorage.getItem('propinatural-bag')||'{}');for(const p of products){if(Number.isInteger(saved[p.id])&&saved[p.id]>0)bag[p.id]=Math.min(saved[p.id],99)}}catch{}
const $=s=>document.querySelector(s);let toastTimer;let activeFilter='all';let detailId=null;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function saveBag(){try{localStorage.setItem('propinatural-bag',JSON.stringify(bag))}catch{}$('#bag-count').textContent=Object.values(bag).reduce((a,b)=>a+b,0);renderBag()}
function addProduct(id){if(!products.some(p=>p.id===id))throw new Error('Unknown product');bag[id]=Math.min((bag[id]||0)+1,99);saveBag();notify(uiText[language].added);return{id,quantity:bag[id]}}
function renderProducts(filter=activeFilter){activeFilter=filter;$('#products').innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(localizedProduct).map(p=>`<article class="product-card"><div class="product-photo"><img src="${p.image}" alt="${p.name} ${uiText[language].photograph}" loading="lazy" width="1000" height="1000"><span class="product-tag">${p.tag}</span></div><h3>${p.name}</h3><p>${p.subtitle}</p><p class="product-price">${formatPrice(p.price)}</p><div class="product-actions"><button class="details-button" data-detail="${p.id}">${uiText[language].details}</button><button class="add-button" data-add="${p.id}" aria-label="${uiText[language].add(p.name)}">+</button></div></article>`).join('')}
function renderBag(){const selected=products.filter(p=>bag[p.id]);$('#bag-items').innerHTML=selected.length?selected.map(localizedProduct).map(p=>`<div class="bag-item"><img src="${p.image}" alt=""><div><h3>${p.name}</h3><p class="bag-price">${formatPrice(p.price)} · ${formatPrice(p.price * bag[p.id])}</p><div class="quantity"><button data-decrease="${p.id}" aria-label="${uiText[language].decrease(p.name)}">−</button><span>${bag[p.id]}</span><button data-add="${p.id}" aria-label="${uiText[language].increase(p.name)}">+</button></div></div><button class="remove" data-remove="${p.id}">${uiText[language].remove}</button></div>`).join(''):'<p>'+uiText[language].empty+'</p>'; if(selected.length) $('#bag-items').innerHTML += `<div class="bag-total"><span>Total</span><strong>${formatPrice(selected.reduce((sum,p)=>sum+p.price*bag[p.id],0))}</strong></div>`;updateInquiry(selected);}
function showDetails(id){detailId=id;const p=localizedProduct(products.find(p=>p.id===id));$('#product-detail').innerHTML=`<img src="${p.image}" alt="${p.name} ${uiText[language].photograph}"><p class="eyebrow">${p.tag}</p><h2>${p.name}</h2><p class="product-price">${formatPrice(p.price)}</p><p>${p.description}</p><p class="bag-note">${uiText[language].preview}</p><button class="button" data-add="${p.id}">${uiText[language].save} <span>+</span></button>`;if(!$('#product-dialog').open)$('#product-dialog').showModal()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),detail=e.target.closest('[data-detail]'),remove=e.target.closest('[data-remove]'),decrease=e.target.closest('[data-decrease]'),filter=e.target.closest('[data-filter]');if(add)addProduct(add.dataset.add);if(detail)showDetails(detail.dataset.detail);if(remove){delete bag[remove.dataset.remove];saveBag()}if(decrease){if(--bag[decrease.dataset.decrease]===0)delete bag[decrease.dataset.decrease];saveBag()}if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts(filter.dataset.filter)}if(e.target.closest('.close'))e.target.closest('dialog').close()});
$('#open-bag').addEventListener('click',()=>$('#bag-dialog').showModal());$('#continue-shopping').addEventListener('click',()=>{$('#bag-dialog').close();$('#shop').scrollIntoView()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#year').textContent=new Date().getFullYear();renderProducts();saveBag();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_product_to_preview_bag',description:'Save a product to the local preview bag. Does not place an order or charge a payment.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:products.map(p=>p.id)}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.productId!=='string'||Object.keys(input).some(k=>k!=='productId'))throw new Error('Provide only a valid productId');return addProduct(input.productId)}})).catch(()=>{})}catch{}}


document.addEventListener('languagechange',()=>{renderProducts();renderBag();if(document.querySelector('#product-dialog').open&&detailId)showDetails(detailId);clearTimeout(toastTimer);document.querySelector('#toast').classList.remove('visible');});

function updateInquiry(selected){const link=document.querySelector('#bag-inquiry');link.hidden=!selected.length;const greeting=language==='es'?'Hola, me gustaría consultar disponibilidad para:':'Hello, I would like to ask about availability for:';const lines=selected.map(localizedProduct).map(p=>bag[p.id]+' × '+p.name+' — '+formatPrice(p.price*bag[p.id]));const total=selected.reduce((sum,p)=>sum+p.price*bag[p.id],0);link.href='https://wa.me/573242515190?text='+encodeURIComponent([greeting,...lines,'Total: '+formatPrice(total),language==='es'?'¿Me confirman disponibilidad y costo de envío?':'Could you confirm availability and delivery cost?'].join('\n'));}
